<nav class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var index = i;
        var stepClass = GetStepClass(index);
        <div class="step @stepClass" @onclick="() => OnStepClick(index)">
            <div class="step-circle">
                @if (index < CurrentStep)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    <span>@(index + 1)</span>
                }
            </div>
            <span class="step-label">@StepNames[index]</span>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(index < CurrentStep ? "completed" : "")"></div>
        }
    }
</nav>

