@namespace sv_a56682ae91a947f2b4d2493126c56d9d.Components.Pages.Apply

<nav class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var index = i;
        var stepClass = GetStepClass(index);
        <div class="step @stepClass" @onclick="() => OnStepClick(index)">
            <div class="step-circle">
                @if (index < CurrentStep)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    <span>@(index + 1)</span>
                }
            </div>
            <span class="step-label">@StepNames[index]</span>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(index < CurrentStep ? "completed" : "")"></div>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private string GetStepClass(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "future";
    }

    private async Task OnStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(index);
        }
    }
}

