toolArgs.old_str:
@namespace sv_a56682ae91a947f2b4d2493126c56d9d.Components.Pages.Apply

<div class="reference-form">
    <h4>Reference @(Index + 1)</h4>

    @if (ShowRemove)
    {
        <button class="btn-remove" @onclick="HandleRemove">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Name" @oninput="e => { Name = e.Value?.ToString() ?? ""; NotifyChanged(); }" placeholder="Reference name" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Relationship" @oninput="e => { Relationship = e.Value?.ToString() ?? ""; NotifyChanged(); }" placeholder="e.g., Former Manager" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @oninput="e => { Email = e.Value?.ToString() ?? ""; NotifyChanged(); }" placeholder="reference@example.com" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @oninput="e => { Phone = e.Value?.ToString() ?? ""; NotifyChanged(); }" placeholder="(555) 123-4567" />
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<ReferenceData> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new ReferenceData(Index, Name, Relationship, Email, Phone));
    }

    private async Task HandleRemove()
    {
        await OnRemove.InvokeAsync();
    }

    public record ReferenceData(int Index, string Name, string Relationship, string Email, string Phone);
}

