    @if (ShowRemove)
    {
        <button class="btn-remove" @onclick="HandleRemove">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Name" @oninput="OnNameInput" placeholder="Reference name" />
